#!/usr/bin/env python3
"""Render the Lombok homepage and Sunset Beach Yoga design example."""
import html,json,re
from pathlib import Path
from urllib.parse import urlencode
ROOT=Path(__file__).resolve().parents[1]
VERSION='20261117-agenda-v1'
e=lambda x:html.escape(str(x),quote=True)
fs=[f for f in json.loads((ROOT/'data/facilitators.json').read_text()) if f.get('publicationStatus')!='review']
by={f['id']:f for f in fs}
places=[('kuta','Kuta & south coast','Studios, retreats & coastal spaces',['Kuta Lombok','Bumbang Beach, South Lombok']),('selong-belanak','Selong Belanak','Yoga & wellness, near the waves',['Selong Belanak']),('senggigi','Senggigi','Spa, movement & a quieter coast',['Kerandangan / Senggigi']),('gili-air','Gili Air','Small-island studios & community',['Gili Air']),('gili-trawangan','Gili Trawangan','Beachside yoga & island energy',['Gili Trawangan']),('gili-meno','Gili Meno','A slower place to move & unwind',['Gili Meno'])]
practice_notes={'Yoga':'Move, stretch & explore','Sound healing':'Discover a sound session','Massage':'Make time for bodywork','Breathwork':'Explore guided breath sessions','Meditation':'A moment to pause','Reiki':'Meet local practitioners','Cacao ceremony':'Find a gathering','Retreats':'Stay a little longer'}
def href(practice='',place=''):
 q={k:v for k,v in [('practice',practice),('place',place)] if v}
 return '/facilitators/'+('?' + urlencode(q) if q else '')
def brand():return '<img class="brand-lotus" src="/assets/images/brand/holistic-tribe-lotus.webp" alt="" width="64" height="64" /><img class="brand-wordmark" src="/assets/images/brand/holistic-tribe-wordmark.webp" alt="Holistic Tribe" width="224" height="75" /><span class="brand-destination">Lombok</span>'
def header(home=False):
 return '<div class="topbar"><div class="container"><nav class="nav" aria-label="Main navigation"><a class="brand" href="/" aria-label="Holistic Tribe Lombok home">'+brand()+'</a><button class="menu-toggle" type="button" aria-label="Open menu" aria-expanded="false" data-menu-toggle>☰</button><div class="nav-links" data-nav-links><a href="/facilitators/">Explore</a><a href="/agenda/">Agenda</a><a href="/#places">Places</a><a href="/holistic-practices/">Guides</a><a href="/about/">Our story</a><a class="nav-provider" href="/contact/#facilitators">For providers <span aria-hidden="true">↗</span></a></div></nav></div></div>'
def footer():
 return '''<footer class="footer island-footer"><div class="container footer-grid"><div><a class="brand footer-brand" href="/" aria-label="Holistic Tribe Lombok home">'''+brand()+'''</a><p>Discover local places, people and experiences.<br>Connect directly. Enjoy the island at your pace.</p><div class="footer-socials"><a href="https://www.instagram.com/holistictribelombok/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.facebook.com/profile.php?id=61565303948298" target="_blank" rel="noopener">Facebook ↗</a></div></div><div><small>Explore the island</small><a href="/facilitators/">All providers</a><a href="/agenda/">Agenda</a><a href="/holistic-practices/">Practice guides</a><a href="/holistic-travel-guides/">Lombok travel guides</a></div><div><small>Be part of the tribe</small><a href="/contact/#facilitators">Get listed for free</a><a href="/contact/#events">Share an event</a><a href="mailto:hello@holistictribelombok.com">Contact us</a><a href="https://holistictribe.nl/" target="_blank" rel="noopener">Discover Holistic Tribe Netherlands ↗</a></div></div><div class="container footer-bottom"><span>© 2026 Holistic Tribe Lombok</span><span>Schedules and availability can change. Please check with the provider.</span></div></footer>'''
def head(title,description,path='/',image='/assets/images/general/holistic-tribe-lombok-hero-refined.webp'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /><title>{e(title)}</title><meta name="description" content="{e(description)}" /><link rel="canonical" href="https://www.holistictribelombok.com{path}" /><meta property="og:title" content="{e(title)}" /><meta property="og:description" content="{e(description)}" /><meta property="og:type" content="website" /><meta property="og:image" content="https://www.holistictribelombok.com{image}" /><meta name="theme-color" content="#f8f5ed" /><link rel="icon" href="/assets/images/brand/holistic-tribe-lotus.webp" /><link rel="preconnect" href="https://fonts.googleapis.com" /><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin /><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet" /><link rel="stylesheet" href="/assets/css/styles.css?v={VERSION}" /><link rel="stylesheet" href="/assets/css/island.css?v={VERSION}" /></head>'''
def end(page):return f'<script src="/data/site-data.js"></script><script src="/assets/js/main.js?v={VERSION}"></script><script src="/assets/js/island.js?v={VERSION}"></script><script>window.HolisticTribe && window.HolisticTribe.init(\'{page}\');</script></body></html>'
def card(f):
 tags={4:['Sound healing','Reiki'],20:['Massage','Yoga'],25:['Massage']}.get(f['id'],f['categories'][:2])
 visual='<img src="'+e(f['image'])+'" alt="'+e(f['name'])+'" loading="lazy" width="600" height="400" />' if f.get('image','').startswith('/assets/') else '<span class="provider-monogram" aria-hidden="true">'+e(f.get('logoText','HT'))+'</span><span class="provider-visual-label">'+e(tags[0])+'</span>'
 return '<a class="island-provider-card" href="'+f['url']+'"><div class="provider-visual tone-'+str(f['id']%4)+'">'+visual+'</div><div class="provider-copy"><span class="small-label">'+e(f['region'])+'</span><h3>'+e(f['name'])+'</h3><p>'+e(f['description'])+'</p><div class="provider-card-bottom"><span>'+e(' · '.join(tags))+'</span><span class="round-arrow" aria-hidden="true">↗</span></div></div></a>'

def main():
 options='<option value="">Anything holistic</option>'+''.join('<option>'+e(k)+'</option>' for k in practice_notes)
 place_options='<option value="">Lombok & all Gili Islands</option>'+''.join('<option value="'+key+'">'+label+'</option>' for key,label,_,_ in places)
 practices=''.join('<a class="practice-tile" href="'+href(k)+'"><span class="practice-index">'+str(i+1).zfill(2)+'</span><h3>'+e(k)+'</h3><p>'+e(note)+'</p><span class="practice-count">'+str(sum(k in f['categories'] for f in fs))+' provider'+('' if sum(k in f['categories'] for f in fs)==1 else 's')+' <span aria-hidden="true">↗</span></span></a>' for i,(k,note) in enumerate(practice_notes.items()))
 place_links=''.join('<a class="place-tile" href="'+href(place=key)+'"><span class="small-label">'+str(sum(f['region'] in regions for f in fs))+' provider'+('' if sum(f['region'] in regions for f in fs)==1 else 's')+'</span><h3>'+label+'</h3><p>'+desc+'</p><span aria-hidden="true">↗</span></a>' for key,label,desc,regions in places)
 featured=''.join(card(f) for f in sorted(fs,key=lambda f:(not f.get('contentSubmitted',False),f.get('editorialOrder',99))))
 home=head('Yoga, sound healing & wellness in Lombok | Holistic Tribe','Discover yoga, sound healing, massage, breathwork and retreats in Lombok and the Gili Islands. Find local providers and connect directly.')+'<body class="island-home" data-page="home">'+header(True)+f'''
<main>
<section class="container island-hero" aria-labelledby="home-title">
 <div class="island-hero-copy"><span class="small-label hero-label">Lombok & the Gili Islands</span><h1 id="home-title">Find your<br><em>holistic facilitator.</em></h1><p class="hero-intro">Yoga, sound healing, massage & more.<br>Discover local people and places, and find something you’d love to experience.</p>
 <form class="island-search" action="/facilitators/" method="get"><div class="search-field"><label for="home-practice">What would you like to try?</label><select id="home-practice" name="practice">{options}</select></div><div class="search-field"><label for="home-place">Where are you staying?</label><select id="home-place" name="place">{place_options}</select></div><button class="island-button" type="submit">Let’s explore <span aria-hidden="true">↗</span></button></form>
 <div class="hero-facts"><span><i></i>{len(fs)} local providers</span><span>Free to explore</span><span>Connect directly</span></div>
 </div>
 <figure class="island-hero-photo"><img src="/assets/images/general/holistic-tribe-lombok-hero-refined.webp" alt="Tropical island illustration with palms, a golden sunset and a quiet yoga moment by the sea" width="1672" height="941" fetchpriority="high" /></figure>
</section>
<section class="container island-section" id="providers"><div class="island-section-heading"><div><span class="small-label">The people & places</span><h2>Meet the island tribe.</h2></div><a class="island-text-link" href="/facilitators/">Search & filter providers <span aria-hidden="true">↗</span></a></div><div class="island-provider-grid">{featured}</div></section>
<section class="container island-section" id="practices"><div class="island-section-heading"><div><span class="small-label">Follow your curiosity</span><h2>What brings you here?</h2></div><p>Know what you’re looking for, or try something new.<br>Start with a practice that catches your eye.</p></div><div class="practice-tiles">{practices}</div></section>
<section class="places-section" id="places"><div class="container island-section"><div class="island-section-heading"><div><span class="small-label">Around the island</span><h2>Find your little corner.</h2></div><p>Stay close to where you are, or explore another part<br>of Lombok and the Gili Islands.</p></div><div class="place-tiles">{place_links}</div></div></section>

<section class="container island-week"><div><span class="small-label">Classes & events in Lombok</span><h2>Weekly classes.<br>Upcoming events.</h2><p>Browse regular lessons by weekday, or find a workshop, retreat or event for your travel dates.</p><a class="island-button light" href="/agenda/">View weekly classes <span aria-hidden="true">↗</span></a></div><div class="week-note"><span class="week-number" aria-hidden="true">01 — 02 — 03</span><h3>Find. Connect. Experience.</h3><p>Explore the options, open a profile and go straight to the provider’s booking page or contact details.</p><a href="/agenda/?view=events">See upcoming events ↗</a></div></section>
<section class="container island-section"><div class="island-section-heading"><div><span class="small-label">A little guidance</span><h2>Curious? Start here.</h2></div><a class="island-text-link" href="/holistic-practices/">All practice guides ↗</a></div><div class="island-guide-grid"><a href="/holistic-practices/sound-healing/"><span class="small-label">Sound healing</span><h3>What happens<br>at a sound bath?</h3><p>A simple introduction to bowls, gongs and listening.</p><span>Read the guide ↗</span></a><a href="/holistic-practices/breathwork/"><span class="small-label">Breathwork</span><h3>Find your way<br>into breathwork.</h3><p>Understand the different session styles before you choose.</p><span>Read the guide ↗</span></a><a href="/holistic-travel-guides/"><span class="small-label">Lombok travel guides</span><h3>A little island<br>inspiration.</h3><p>Practical ideas for exploring Lombok at a gentler pace.</p><span>Explore the guides ↗</span></a></div></section>
<section class="container island-provider-invite"><div><span class="small-label">For local practitioners & spaces</span><h2>You do your thing.<br>We help people find it.</h2><p>Share your classes, sessions or retreat space with people curious about holistic Lombok. Your profile stays free.</p></div><a class="island-button" href="/contact/#facilitators">Join Holistic Tribe <span aria-hidden="true">↗</span></a></section>
</main>'''+footer()+end('island-home')
 (ROOT/'index.html').write_text(home)
 f=by[13]
 photos=[('sunset-beach-yoga-ocean-pavilion.webp','The open-air pavilion by the beach'),('sunset-beach-yoga-flyhigh-shala.webp','The FlyHigh Yoga setup inside the shala'),('sunset-beach-yoga-beach-hut-flowers.webp','The beachside space framed by flowers'),('sunset-beach-yoga-flyhigh-ocean.webp','Ocean views from the yoga space')]
 photo_buttons=''.join('<button class="profile-photo photo-'+str(i)+'" type="button" data-photo="/assets/images/sunset-beach-yoga/'+file+'" data-caption="'+e(caption)+'" aria-label="Open photo: '+e(caption)+'"><img src="/assets/images/sunset-beach-yoga/'+file+'" alt="'+e(caption)+'" width="1200" height="1400" '+('fetchpriority="high"' if i==0 else 'loading="lazy"')+' />'+('<span class="photo-counter">View all 4 photos ↗</span>' if i==0 else '')+'</button>' for i,(file,caption) in enumerate(photos))
 sample=head('Sunset Beach Yoga, Gili Trawangan | Holistic Tribe Lombok','Explore beachside Morning Flow and FlyHigh Yoga at Sunset Beach Yoga on Gili Trawangan. See the space and contact the team for the current schedule.',f['url'],'/assets/images/sunset-beach-yoga/sunset-beach-yoga-ocean-pavilion.webp')+'<body class="island-profile" data-page="profile">'+header()+f'''
<main class="container island-profile-main"><nav class="profile-breadcrumbs" aria-label="Breadcrumb"><a href="/facilitators/">Explore</a><span>/</span><a href="/facilitators/?place=gili-trawangan">Gili Trawangan</a><span>/</span><span>Sunset Beach Yoga</span></nav>
<div class="island-profile-title"><div><span class="small-label">Beachside yoga · Gili Trawangan</span><h1>Sunset Beach Yoga</h1><p>Move a little. Take in the ocean.</p></div><a class="island-button" href="{e(f['links']['whatsapp'])}" target="_blank" rel="noopener">Ask about a class ↗</a></div>
<section class="island-photo-board" aria-label="Photos of Sunset Beach Yoga">{photo_buttons}</section>
<div class="island-profile-layout"><div class="island-profile-story"><section id="about"><span class="small-label">The place</span><h2>Yoga with a sea breeze.</h2><p>Sunset Beach Yoga is a beachside yoga space on Gili Trawangan, with an open-air pavilion and views towards the ocean. Morning Flow and FlyHigh Yoga are part of its offering.</p><p>Come for a little movement during your island stay, or get in touch to ask which class would suit you. The team’s WhatsApp and Instagram are the best places to check the latest schedule before visiting.</p><div class="profile-practice-tags"><span>Yoga</span><span>Morning Flow</span><span>FlyHigh Yoga</span><span>Beachside setting</span></div></section>
<section class="profile-experiences"><span class="small-label">What you can explore</span><h2>Find a class for your day.</h2><div class="experience-row"><span class="experience-no">01</span><div><h3>Morning Flow</h3><p>A yoga practice to start your island day. Ask the team for the current class time and format.</p></div></div><div class="experience-row"><span class="experience-no">02</span><div><h3>FlyHigh Yoga</h3><p>Try the studio’s FlyHigh setup in an ocean-view space. Check suitability and availability with the team.</p></div></div></section>
<details class="profile-sources"><summary>Sources & information <span aria-hidden="true">+</span></summary><p>Public sources reviewed on 17 November 2026. The provider-managed accommodation listing supports the yoga offering and WhatsApp number. Current class times and prices have not been confirmed directly.</p><a href="https://www.airbnb.com/rooms/1724086" target="_blank" rel="noopener">Provider-managed accommodation listing ↗</a><p>Are you the provider? <a href="mailto:hello@holistictribelombok.com">Send us an update</a>. Your profile and changes are free.</p></details></div>
<aside class="profile-visit-card" id="contact"><span class="small-label">Good to know</span><h2>Your next<br>island moment.</h2><dl><div><dt>Where</dt><dd>Sunset Beach area<br>Gili Trawangan</dd></div><div><dt>Classes</dt><dd>Morning Flow & FlyHigh Yoga</dd></div><div><dt>Schedule & price</dt><dd>Check this week’s details with the team.</dd></div><div><dt>First time?</dt><dd>Ask which class fits your experience.</dd></div></dl><a class="island-button" href="{e(f['links']['whatsapp'])}" target="_blank" rel="noopener">Message on WhatsApp ↗</a><a class="visit-secondary" href="{e(f['links']['instagram'])}" target="_blank" rel="noopener">See the latest on Instagram ↗</a><a class="visit-map" href="{e(f['links']['map'])}" target="_blank" rel="noopener">Find the studio on Google Maps ↗</a><p class="quiet-note">Please confirm the meeting point and availability before heading over.</p></aside></div>
<section class="profile-explore-more"><div><span class="small-label">Keep exploring</span><h2>More island possibilities.</h2><p>Compare other yoga spaces or see what’s available on Gili Trawangan.</p></div><div><a class="island-button" href="/facilitators/?practice=Yoga">Explore yoga ↗</a><a class="island-text-link" href="/facilitators/?place=gili-trawangan">More on Gili Trawangan ↗</a></div></section>
</main><dialog class="island-photo-dialog" data-photo-dialog aria-label="Sunset Beach Yoga photos"><button class="photo-dialog-close" type="button" data-photo-close aria-label="Close photos">×</button><button class="photo-dialog-prev" type="button" data-photo-prev aria-label="Previous photo">←</button><figure><img data-photo-large alt="" /><figcaption data-photo-caption></figcaption></figure><button class="photo-dialog-next" type="button" data-photo-next aria-label="Next photo">→</button></dialog>'''+footer()+end('profile')
 (ROOT/('facilitators/'+f['slug']+'/index.html')).write_text(sample)
 print('Rendered island homepage and Sunset Beach Yoga profile.')
if __name__=='__main__':main()
